import { FlatList, View, Text, StyleSheet } from 'react-native';
import { theme } from '../theme';
import { MessageBubble, type ChatMessage } from './MessageBubble';

type MessageListProps = {
  messages: ChatMessage[];
  currentUserId: string;
};

const MONTHS_SHORT = [
  'янв',
  'фев',
  'мар',
  'апр',
  'мая',
  'июн',
  'июл',
  'авг',
  'сен',
  'окт',
  'ноя',
  'дек',
] as const;

function startOfDay(d: Date): number {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

function sameDay(a: Date, b: Date): boolean {
  return startOfDay(a) === startOfDay(b);
}

function formatDayLabel(iso: string): string {
  const d = new Date(iso);
  const now = new Date();
  if (sameDay(d, now)) {
    return 'сегодня';
  }
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (sameDay(d, yesterday)) {
    return 'вчера';
  }
  return `${d.getDate()} ${MONTHS_SHORT[d.getMonth()]}`;
}

/** Newest-first data for inverted FlatList (newest at bottom). */
export function MessageList({ messages, currentUserId }: MessageListProps) {
  return (
    <FlatList
      data={messages}
      inverted
      keyExtractor={(item) => item.id}
      contentContainerStyle={styles.content}
      keyboardShouldPersistTaps="handled"
      renderItem={({ item, index }) => {
        const older = messages[index + 1];
        const itemDay = new Date(item.createdAt);
        const showDate =
          !older || !sameDay(itemDay, new Date(older.createdAt));
        const isMine = item.senderId === currentUserId;
        const showSenderName =
          !isMine &&
          (!older ||
            older.senderId !== item.senderId ||
            !sameDay(itemDay, new Date(older.createdAt)));

        return (
          <View>
            <MessageBubble
              message={item}
              isMine={isMine}
              showSenderName={showSenderName}
            />
            {showDate ? (
              <View style={styles.dateWrap}>
                <Text style={styles.dateText}>
                  {formatDayLabel(item.createdAt)}
                </Text>
              </View>
            ) : null}
          </View>
        );
      }}
    />
  );
}

const styles = StyleSheet.create({
  content: {
    paddingVertical: theme.spacing.sm,
    flexGrow: 1,
  },
  dateWrap: {
    alignItems: 'center',
    marginVertical: theme.spacing.sm,
  },
  dateText: {
    color: theme.colors.muted,
    fontSize: theme.typography.caption.fontSize,
    backgroundColor: theme.colors.surface,
    overflow: 'hidden',
    paddingHorizontal: theme.spacing.md,
    paddingVertical: 4,
    borderRadius: 12,
    overflow: 'hidden',
    textTransform: 'capitalize',
  },
});
EOF
